  dup.onclick=async()=>{const rs2=pick();if(rs2.length!==1){toast('Select one order');return;}const o=rs2[0];const nid=prompt('New KM order ID?',(o.order_id||o._id)+'-2');if(!nid)return;const d=Object.assign({},o);['_id','_u','payout_status','payout_date'].forEach(k=>delete d[k]);d.order_id=nid;d.status='To place';d.payout_status='Pending';const r={_id:nid};if(await save(r,d)){all.push(r);SEL.clear();draw();}};
