 /* ---------- Waiting KM confirmation ---------- */
 function confirmT(P){const km=KMO().filter(r=>DONE(r.status)&&!confirmedOn(r)&&r.payout_status!=='Received');
  const a=km.filter(r=>!gv(r,'mrn_updated')),b=km.filter(r=>gv(r,'mrn_updated'));
  P.appendChild(el('p','bb-meta ov-note','Flow: reaches KM → we update MRN on the KM portal → KM sends a confirmation mail → payout 7 days after that.'));
  const sec=(t,n)=>{const s=el('div','bb-sech');s.appendChild(el('span',null,t));s.appendChild(el('small',null,n));P.appendChild(s);};
  const card=(r,step)=>{const w=step==='mrn'?days(gv(r,'delivered_km')):days(gv(r,'mrn_updated'));const late=step==='cf'&&w>=3;const c=el('div','bb-cd'+(late?' late':''));const h=el('div','cd-h');const hl=el('div');hl.appendChild(el('b',null,r.order_id||r._id));hl.appendChild(el('small',null,r.item));h.appendChild(hl);h.appendChild(el('div','cd-amt',inr(r.payout)));c.appendChild(h);
   c.appendChild(el('p','bb-meta',step==='mrn'?'Reached KM '+(gv(r,'delivered_km')||'—')+(w!=null?' · '+w+' days':''):'MRN updated '+gv(r,'mrn_updated')+(w!=null?' · waiting '+w+' days':'')));
   const fa=el('div','cd-act');
   if(step==='mrn')fa.appendChild(btn('✓ MRN updated on KM portal',async()=>{if(await save(r,{mrn_updated:today()}))draw();},'bb-b sm'));
   else{fa.appendChild(btn('✓ Confirmation received',async()=>{if(await save(r,{mrn_confirmed:today(),payout_timer:today()})){toast('7-day payout timer started');draw();}},'bb-b sm'));if(late)fa.appendChild(wa('WhatsApp KM','Hi Maanvesh, MRN for '+(r.order_id||r._id)+' ('+r.item+') was updated on '+gv(r,'mrn_updated')+'. Confirmation has not come yet, please check. Thanks!'));}
   c.appendChild(fa);return c;};
  sec('① MRN update pending',a.length+' orders');if(a.length){const g=el('div','bb-grid');a.forEach(r=>g.appendChild(card(r,'mrn')));P.appendChild(g);}else P.appendChild(el('p','bb-meta','Nothing.'));
  sec('② MRN done · waiting for KM confirmation',b.length+' orders · '+inr(sumP(b)));
  if(b.length){const all2=btn('✓ Confirmation received for all '+b.length,async()=>{if(!confirm(b.length+' orders: mark confirmation received today? (starts the 7-day timer)'))return;for(const r of b)await save(r,{mrn_confirmed:today(),payout_timer:today()});draw();});all2.style.marginBottom='10px';P.appendChild(all2);const g=el('div','bb-grid');b.sort((x,y)=>String(gv(x,'mrn_updated')).localeCompare(String(gv(y,'mrn_updated')))).forEach(r=>g.appendChild(card(r,'cf')));P.appendChild(g);}else P.appendChild(el('p','bb-meta','Nothing.'));}

