 const AG=[['mail','📬','Mail agent','Every 2 hours · Gmail → portal'],['pricing','💰','Bid pricing agent','Every 2 hours · store price + margin for new bids'],['tracking','🚚','Tracking agent','Every 4 hours · checks all tracking'],['ops','📋','Ops agent','8:41am + 7:41pm · today\'s tasks + drafts'],['payout','💸','Payout agent','Daily 10:52 · confirmation + 7 days, chase'],['auditor','🛡️','Auditor agent','Every 3 hours · anything missed?'],['reconciler','🔍','KM Reconciler','9:23am + 9:23pm · KM All Orders vs portal (cancel, payout, US IDs)'],['brain','🧠','Brain (Chief of Staff)','Hourly · chat photos / voice / notes → orders'],['cfo','📊','CFO agent','9:37am + 9:37pm · money, bank, target (Money tab)'],['qa','🧪','QA / health','Every 6 hours · site, functions, data health'],['clientdesk','👥','Client Desk','Hourly · end-client portal activity']];
