  if(!rows.length){const words=t.toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(w=>w.length>3&&!['order','wala','karo','diya','gaya','liya','mere','paas','abhi','hogaya','deliver','landed','payment','paisa','cost','costing','profit','rate','each','sabme','total'].includes(w));
   const cands=all.filter(r=>!/cancel/i.test(r.status||'')&&(out.client?r.client===out.client:(finy||hasAmt||QP_SUMQ.test(t)||r.payout_status!=='Received'))).map(r=>{const it=String(r.item||'').toLowerCase()+' '+String(r.client||'').toLowerCase();const hit=words.filter(w=>it.includes(w)).length;return [r,hit];}).filter(([r,h])=>h>=1).sort((a,b)=>b[1]-a[1]);
   if(cands.length&&(cands.length===1||cands[0][1]>cands[1][1]))rows=[cands[0][0]];else if(cands.length>1){out.cands=cands.slice(0,4).map(c=>c[0]);out.notes.push('More than one order matches: '+out.cands.map(c=>c._id).join(', '));}}
  if(/\b(weight|kg|wajan|vajan|reship(?:ping)? cost|shipping cost|courier cost|kitna lagega|andaza|estimate)\b/i.test(t)&&!finy){out.wsum=true;out.notes=[];const open=r=>['In transit to reshipper','At reshipper','Shipped from hub'].includes(r.status);out.orders=rows.length?rows:(rsName?all.filter(r=>gv(r,'reshipper')===rsName&&open(r)):cli?all.filter(r=>r.client===cli&&open(r)):all.filter(open));return out;}
  if(QP_SUMQ.test(t)&&!finy&&!ids.length){out.summary=true;out.notes=[];out.orders=rows.length?rows:(cli?all.filter(r=>r.client===cli&&!/cancel/i.test(r.status||'')):[]);return out;}
  out.orders=rows;if(!rows.length){const r0=null;for(const [re,fn,label] of QP_RULES){if(re.test(t)){try{out.patch=Object.assign(out.patch||{},fn({client:''}));out.label=label;}catch(e){}}}
   if(fin.patch.fx&&Object.keys(fin.patch).length===1){out.global={fx:fin.patch.fx};out.label='FX rate '+fin.patch.fx;out.patch=null;}return out;}
