  btn('Bids (CSV)','All KM bids won',()=>dl('luxella-bids',['KM orders','Items','Payout','Won','Accept by','Dismissed'],BIDS.map(b=>[(b.km_order_ids||[]).join(' '),(b.items||[]).map(x=>x.name).join(' + '),b.payout_inr,String(b.won_at).slice(0,10),b.accept_by,b.dismissed?'yes':''])));
  btn('Store orders (CSV)','USA/UK/Canada purchases',()=>dl('luxella-store-orders',['Store','Order no','Date','Account','Items','Total $','Status','Tracking','KM'],BUYS.map(b=>[b.store,b.store_order_no,b.order_date,b.recipient,(b.items||[]).map(x=>x.name).join(' + '),b.total_usd,b.status,(b.tracking_numbers||[]).join(' '),(b.km_ids||[]).join(' ')])));
  btn('Profit by month (CSV)','Payout, landed, profit per month',()=>{const m={};km.forEach(r=>{const k=String(r.order_date||'').slice(0,7)||'?';m[k]=m[k]||[0,0,0,0];m[k][0]++;m[k][1]+=Number(r.payout)||0;m[k][2]+=Number(r.landed)||0;m[k][3]+=Number(r.profit)||0;});dl('luxella-profit-month',['Month','Orders','Payout ₹','Landed ₹','Profit ₹'],Object.entries(m).sort().map(([k,v])=>[k,...v.map(x=>Math.round(x))]));});
  btn('MRN-ready list (CSV)','Reached KM, MRN pending',()=>dl('luxella-mrn-pending',['KM order','Item','Reached KM','Courier','Tracking'],km.filter(r=>DONE(r.status)&&!gv(r,'mrn_updated')).map(r=>[r.order_id||r._id,r.item,gv(r,'delivered_km'),gv(r,'km_courier'),gv(r,'km_tracking')])));
  btn('Full backup (JSON)','All data (orders, bids, store orders)',()=>dl('luxella-b2b-backup',null,{orders:all,bids:BIDS,store_orders:BUYS,at:new Date().toISOString()},'json'));
  btn('Copy summary for WhatsApp','Today\'s status in one message',async()=>{const open=km.filter(r=>!DONE(r.status));const pen=km.filter(r=>r.payout_status!=='Received');const t='Luxella B2B · '+today()+'\nOpen orders: '+open.length+'\nAt hub: '+km.filter(r=>r.status==='At reshipper').length+'\nTo India: '+km.filter(r=>r.status==='Shipped from hub').length+'\nPayout pending: '+inr(pen.reduce((t2,r)=>t2+(Number(r.payout)||0),0))+' ('+pen.length+')';try{await navigator.clipboard.writeText(t);toast('Copied');}catch(e){}});
  btn('Print current view','Browser print / PDF',()=>window.print());
